// wire-visible (a `DBF_MENU` field is served as `DBR_ENUM`), so the order
// here is the `.dbd` declaration order, verbatim.
// ---------------------------------------------------------------------

/// `menu(epidFeedbackMode)`
pub static MENU_EPID_FEEDBACK_MODE: &[&str] = &["PID", "Max/Min"];

/// `menu(epidFeedbackState)`
pub static MENU_EPID_FEEDBACK_STATE: &[&str] = &["Off", "On"];

/// `menu(throttleDRVLC)`
pub static MENU_THROTTLE_DRVLC: &[&str] = &["Off", "On"];

/// `menu(throttleDRVLS)`
pub static MENU_THROTTLE_DRVLS: &[&str] = &["Normal", "Low Limit", "High Limit"];

/// `menu(throttleOV)`
pub static MENU_THROTTLE_OV: &[&str] = &["Ext PV NC", "Ext PV OK", "Local PV", "Constant"];

/// `menu(throttleSTS)`
pub static MENU_THROTTLE_STS: &[&str] = &["Unknown", "Error", "Success"];

/// `menu(throttleSYNC)`
pub static MENU_THROTTLE_SYNC: &[&str] = &["Idle", "Process"];

/// `menu(throttleWAIT)`
